/** Simulated motor-imagery EEG for the BCI Lab demonstration mode.
 *
 *  Everything here is generated by the app; none of it is a measurement. The model follows
 *  a well-established effect: imagining a hand movement reduces the 8–12 Hz "mu" rhythm over
 *  the opposite hemisphere's sensorimotor cortex (event-related desynchronization, ERD).
 *  Left-hand imagery → lower mu power at C4 (right hemisphere); right-hand → lower at C3. */

export type ImageryClass = "left_hand" | "right_hand";
export const IMAGERY_CLASSES: ImageryClass[] = ["left_hand", "right_hand"];
export const IMAGERY_LABEL: Record<ImageryClass, string> = { left_hand: "Left-hand imagery", right_hand: "Right-hand imagery" };

export const SFREQ = 128;
export const TRIAL_SECONDS = 2;
const N = SFREQ * TRIAL_SECONDS;
export const MU_BAND: [number, number] = [8, 12];
/** Fraction of mu amplitude that remains over the contralateral hemisphere during imagery. */
const ERD_FACTOR = 0.55;

export type Trial = { cls: ImageryClass; c3: number[]; c4: number[] };

/** Deterministic PRNG (mulberry32) so demos and tests are reproducible. */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  const u = Math.max(r(), 1e-12);
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r());
}

/** One channel: background activity with a 1/f-like spectrum, a mu rhythm, and sensor noise (µV). */
function channel(r: () => number, muAmp: number, noise: number): number[] {
  const out = new Array<number>(N).fill(0);
  for (let f = 1; f <= 40; f++) {
    const amp = 6 / f;
    const ph = r() * 2 * Math.PI;
    for (let i = 0; i < N; i++) out[i] += amp * Math.sin((2 * Math.PI * f * i) / SFREQ + ph);
  }
  const muF = 9.5 + r() * 2;
  const muPh = r() * 2 * Math.PI;
  for (let i = 0; i < N; i++) {
    // Mu arrives in bursts, so modulate its envelope slowly.
    const env = 0.75 + 0.25 * Math.sin((2 * Math.PI * 0.7 * i) / SFREQ + muPh);
    out[i] += muAmp * env * Math.sin((2 * Math.PI * muF * i) / SFREQ + muPh) + noise * gauss(r);
  }
  return out;
}

/** Generate one 2-second, 2-channel (C3, C4) trial. `noise` is sensor noise in µV. */
export function generateTrial(cls: ImageryClass, noise: number, r: () => number): Trial {
  const base = 10 * (0.85 + 0.3 * r());
  const c3Amp = base * (cls === "right_hand" ? ERD_FACTOR : 1) * (0.85 + 0.3 * r());
  const c4Amp = base * (cls === "left_hand" ? ERD_FACTOR : 1) * (0.85 + 0.3 * r());
  return { cls, c3: channel(r, c3Amp, noise), c4: channel(r, c4Amp, noise) };
}

/** Mean power in [lo, hi] Hz from a direct DFT (µV²). */
export function bandPower(x: number[], sfreq: number, lo: number, hi: number): number {
  const n = x.length;
  const mean = x.reduce((a, b) => a + b, 0) / n;
  let total = 0;
  let bins = 0;
  for (let k = Math.ceil((lo * n) / sfreq); k <= Math.floor((hi * n) / sfreq); k++) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < n; i++) {
      const a = (2 * Math.PI * k * i) / n;
      re += (x[i] - mean) * Math.cos(a);
      im -= (x[i] - mean) * Math.sin(a);
    }
    total += (re * re + im * im) / (n * n);
    bins++;
  }
  return bins ? total / bins : 0;
}

/** Features: log mu-band power at C3 and C4. */
export function features(t: Trial): [number, number] {
  return [Math.log(bandPower(t.c3, SFREQ, ...MU_BAND)), Math.log(bandPower(t.c4, SFREQ, ...MU_BAND))];
}

export type LogReg = { mean: number[]; std: number[]; w: number[]; b: number };

/** Binary logistic regression on standardized features, fitted by gradient descent.
 *  Class 1 = right_hand. */
export function trainLogReg(X: number[][], y: number[], epochs = 400, lr = 0.3): LogReg {
  const d = X[0].length;
  const mean = Array.from({ length: d }, (_, j) => X.reduce((a, r) => a + r[j], 0) / X.length);
  const std = Array.from({ length: d }, (_, j) =>
    Math.sqrt(X.reduce((a, r) => a + (r[j] - mean[j]) ** 2, 0) / X.length) || 1,
  );
  const Z = X.map((r) => r.map((v, j) => (v - mean[j]) / std[j]));
  const w = new Array<number>(d).fill(0);
  let b = 0;
  for (let e = 0; e < epochs; e++) {
    const gw = new Array<number>(d).fill(0);
    let gb = 0;
    Z.forEach((z, i) => {
      const p = 1 / (1 + Math.exp(-(z.reduce((a, v, j) => a + v * w[j], 0) + b)));
      const err = p - y[i];
      z.forEach((v, j) => (gw[j] += err * v));
      gb += err;
    });
    for (let j = 0; j < d; j++) w[j] -= (lr * gw[j]) / Z.length;
    b -= (lr * gb) / Z.length;
  }
  return { mean, std, w, b };
}

/** Probability per class, in IMAGERY_CLASSES order. */
export function predictProba(m: LogReg, x: number[]): [number, number] {
  const z = x.reduce((a, v, j) => a + ((v - m.mean[j]) / m.std[j]) * m.w[j], 0) + m.b;
  const pRight = 1 / (1 + Math.exp(-z));
  return [1 - pRight, pRight];
}

export type DemoModel = { model: LogReg; nTrain: number; nTest: number; testAccuracy: number; noise: number };

/** Train on simulated trials and score on separate held-out simulated trials. */
export function buildDemoModel(seed: number, noise: number, nTrain = 80, nTest = 40): DemoModel {
  const r = rng(seed);
  const make = (n: number) => Array.from({ length: n }, (_, i) => generateTrial(IMAGERY_CLASSES[i % 2], noise, r));
  const train = make(nTrain);
  const test = make(nTest);
  const model = trainLogReg(train.map(features), train.map((t) => (t.cls === "right_hand" ? 1 : 0)));
  const correct = test.filter((t) => {
    const p = predictProba(model, features(t));
    return IMAGERY_CLASSES[p[1] > p[0] ? 1 : 0] === t.cls;
  }).length;
  return { model, nTrain, nTest, testAccuracy: correct / nTest, noise };
}
